SELECT day, amount,
 SUM(amount) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running
FROM daily_sales;

SELECT day, amount,
 amount - LAG(amount) OVER (PARTITION BY product_id ORDER BY day) AS delta
FROM sales;

SELECT name, score,
 RANK() OVER (ORDER BY score DESC) AS r,
 DENSE_RANK() OVER (ORDER BY score DESC) AS dr FROM players;

SELECT name, salary,
 AVG(salary) OVER () AS avg_salary,
 salary - AVG(salary) OVER () AS diff FROM employees;

SELECT day, FIRST_VALUE(amount) OVER (ORDER BY day) AS first_day,
 LAST_VALUE(amount) OVER (ORDER BY day ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS last_day
FROM sales;

